{
  "title": "The Ruined Crown Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team studies a map outside the ruined city.",
      "visual_description": "Three cloaked figures crouched on a windswept hill at dusk, an old parchment map spread between them, the shattered skyline of a royal city in the distance.",
      "characters": ["lead_rescuer", "map_reader", "scout"]
    },
    {
      "scene_number": 2,
      "caption": "They approach the cracked castle gates.",
      "visual_description": "Massive iron-bound gates split down the middle, faded royal banners hanging in tatters, the team silhouetted against torchlight beyond.",
      "characters": ["lead_rescuer", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "A frightened townsperson warns them of patrols.",
      "visual_description": "A hooded villager clutching a basket in a narrow alley, gesturing urgently as the rescuers listen in shadow.",
      "characters": ["lead_rescuer", "frightened_townsperson"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol marches down market street.",
      "visual_description": "Rank of black-plated guards with halberds passing crumbled market stalls, the team flattened against a broken wall.",
      "characters": ["scout", "armored_patrol_captain"]
    },
    {
      "scene_number": 5,
      "caption": "The map reader plots a route past the cursed tower.",
      "visual_description": "Map unrolled on a stone bench, finger tracing a path, the leaning silhouette of a twisted tower looming through a broken window.",
      "characters": ["map_reader", "lead_rescuer"]
    },
    {
      "scene_number": 6,
      "caption": "A magic helper joins the team in an abandoned shrine.",
      "visual_description": "A small glowing figure with floating sleeves stepping out of a cracked stained-glass alcove, dust motes catching candlelight.",
      "characters": ["magic_helper", "lead_rescuer", "map_reader"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon ripple through the ruins.",
      "visual_description": "Townspeople pointing at huge claw marks raked across a stone wall, a distant plume of smoke curling above broken rooftops.",
      "characters": ["frightened_townsperson", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "The scout climbs an old royal banner to spy the courtyard.",
      "visual_description": "A lithe figure scaling a long faded crimson banner pinned to a tower wall, looking down on patrolling guards in a courtyard of statues.",
      "characters": ["scout"]
    },
    {
      "scene_number": 9,
      "caption": "A sleepy official is found dozing at his desk.",
      "visual_description": "A plump robed clerk slumped over an ink-stained ledger in a dusty office, keys dangling from his belt, candle nearly burned out.",
      "characters": ["sleepy_official", "lead_rescuer"]
    },
    {
      "scene_number": 10,
      "caption": "The team bribes the official for a passkey.",
      "visual_description": "A heavy brass key being slid across the desk in exchange for a glittering coin, the official rubbing his eyes.",
      "characters": ["sleepy_official", "lead_rescuer", "magic_helper"]
    },
    {
      "scene_number": 11,
      "caption": "They enter the cursed tower's lower hall.",
      "visual_description": "Spiral staircase wrapped in pale green vines that glow faintly, the team's faces lit from below by ghostly light.",
      "characters": ["lead_rescuer", "scout", "magic_helper"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door bars their way upward.",
      "visual_description": "A tall stone door etched with shifting runes, the magic helper raising glowing hands to read them, the others watching tensely.",
      "characters": ["magic_helper", "lead_rescuer", "map_reader"]
    },
    {
      "scene_number": 13,
      "caption": "The door opens into a mirrored hall.",
      "visual_description": "Endless tall mirrors reflecting the team a hundred times, each reflection slightly different, footsteps echoing on black tile.",
      "characters": ["lead_rescuer", "scout", "magic_helper", "map_reader"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a gilded cage.",
      "visual_description": "A pale figure in tattered finery curled inside an ornate birdcage of gold bars suspended from a vaulted ceiling, chains rattling.",
      "characters": ["lead_rescuer", "captive_noble", "magic_helper"]
    },
    {
      "scene_number": 15,
      "caption": "The patrol captain bursts in, blade drawn.",
      "visual_description": "Armored captain framed in a shattered doorway, sword raised, the team shielding the freed captive behind them.",
      "characters": ["armored_patrol_captain", "lead_rescuer", "scout", "captive_noble"]
    },
    {
      "scene_number": 16,
      "caption": "The magic helper collapses the hall behind them.",
      "visual_description": "A wave of shimmering force shattering mirrors into golden shards, the team running down a corridor as walls buckle.",
      "characters": ["magic_helper", "lead_rescuer", "scout", "map_reader", "captive_noble"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the old plaza toward the bridge.",
      "visual_description": "Cracked plaza tiles, broken fountain in the center, the long stone bridge visible ahead under a blood-orange sky, dragon shadow passing overhead.",
      "characters": ["lead_rescuer", "scout", "map_reader", "magic_helper", "captive_noble"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across the crumbling bridge at dawn.",
      "visual_description": "Long arched bridge over a misty chasm, stones falling away behind their footsteps, first light breaking on distant safe hills.",
      "characters": ["lead_rescuer", "scout", "map_reader", "magic_helper", "captive_noble"]
    }
  ]
}

